const existing = $input.all().map(i => i.json?.Tool_Name || i.json?.name || '');
const newTools = $('A1_Merge_Sources').all().filter(i => {
  const name = i.json?.name || i.json?.title || '';
  return name && !existing.some(e => String(e).toLowerCase() === String(name).toLowerCase());
});
return newTools.length ? newTools.map(t => ({ json: t.json })) : [];

const all = $input.all();
const first5 = all.slice(0, 5);
const staticData = $getWorkflowStaticData('global');
staticData.todayTools = first5;
return first5.map(i => ({ json: i.json }));

const response = $input.first().json;
const loopItem = $('A2_For_Each_Tool').item.json;
const slug = loopItem.Tool_Slug || loopItem.tool_slug || 'tool';
let html = '';
if (Array.isArray(response.content) && response.content[0] && response.content[0].text) html = response.content[0].text;
else if (typeof response.body === 'string') html = response.body;
const base = $env.TEMP_CONTENT || '/temp-content';
const filePath = base + '/tools/' + slug + '.html';
return [{ json: { writeData: { data: html, fileName: filePath } } }];

const staticData = $getWorkflowStaticData('global');
const tools = staticData.todayTools || [];
const tool_a = tools[0]?.json || {};
const tool_b = tools[1]?.json || {};
const slug = (s) => (String(s || '').toLowerCase().replace(/\\s+/g, '-').replace(/[^a-z0-9-]/g, ''));
const slugA = tool_a.Tool_Slug || slug(tool_a['Tool Name']);
const slugB = tool_b.Tool_Slug || slug(tool_b['Tool Name']);
return [{ json: { comparison: { tool_a_name: tool_a['Tool Name'], tool_a_data: tool_a, tool_b_name: tool_b['Tool Name'], tool_b_data: tool_b }, slug_a: slugA, slug_b: slugB } }];

const pickItem = $('A2_Pick_2_For_Comparison').item.json;
const response = $input.first().json;
let html = '';
if (Array.isArray(response.content) && response.content[0] && response.content[0].text) html = response.content[0].text;
else if (typeof response.body === 'string') html = response.body;
const base = $env.TEMP_CONTENT || '/temp-content';
const filePath = base + '/compare/' + (pickItem.slug_a || 'a') + '-vs-' + (pickItem.slug_b || 'b') + '.html';
return [{ json: { writeData: { data: html, fileName: filePath } } }];

const staticData = $getWorkflowStaticData('global');
const tools = staticData.todayTools || [];
const listStr = tools.map((t, i) => (i+1) + '. ' + (t.json?.['Tool Name'] || 'Tool')).join('\n');
const start = new Date();
const end = new Date();
end.setDate(end.getDate() - 7);
const dateRange = end.toISOString().slice(0,10) + ' to ' + start.toISOString().slice(0,10);
const slug = 'new-tools-' + start.toISOString().slice(0,10);
return [{ json: { list_of_tools: listStr, date_range: dateRange, slug } }];

const staticData = $getWorkflowStaticData('global');
const tools = staticData.todayTools || [];
const prep = $input.first().json;
const summary = tools.map(t => ({
  name: t.json?.['Tool Name'] || t.json?.tool_name || 'Tool',
  category: t.json?.Category || t.json?.category || 'General',
  score: t.json?.score || t.json?.Priority || 'N/A',
  price: t.json?.pricing?.lifetime || t.json?.pricing?.monthly || t.json?.Price || 'Check site',
  deal_url: t.json?.deal_url || t.json?.['Deal URL'] || ''
}));
return [{ json: { ...prep, blog_tools_summary: JSON.stringify(summary, null, 2) } }];

