const blogInput = $('A2_Prepare_Blog_Input').item.json;
const response = $input.first().json;
let html = '';
if (Array.isArray(response.content) && response.content[0] && response.content[0].text) html = response.content[0].text;
else if (typeof response.body === 'string') html = response.body;
const base = $env.TEMP_CONTENT || '/temp-content';
const filePath = base + '/blog-' + (blogInput.slug || 'new-tools') + '.html';
return [{ json: { writeData: { data: html, fileName: filePath } } }];

const data = $input.first().json.data || $input.first().binary?.data;
let results = [];
try {
  const str = typeof data === 'string' ? data : (data && data.toString ? data.toString() : JSON.stringify(data));
  results = typeof str === 'string' && str.startsWith('[') ? JSON.parse(str) : [];
} catch (e) {}
const passed = results.filter(r => r.status === 'PASS');
const failed = results.filter(r => r.status === 'FAIL');
return [{ json: { allPass: failed.length === 0, passed, failed, results } }];

const item = $input.first().json;
const failed = item.failed || [];
const tempContent = ($env.TEMP_CONTENT || '/temp-content').replace(/\\/g, '/');
return failed.map(f => {
  let file = (f.file || '').replace(/\\/g, '/');
  if (tempContent && file.indexOf(tempContent) === 0) file = file.slice(tempContent.length).replace(/^\/+/, '');
  return { json: { file, issues: Array.isArray(f.issues) ? f.issues.join('; ') : (f.issues || ''), attempts: 1 } };
});

const staticData = $getWorkflowStaticData('global');
staticData.approvedCount = 0;
return $input.all();

const loopItem = $('A4_Loop_Failed').item.json;
const raw = $input.first().json.data || $input.first().binary?.data;
let html = typeof raw === 'string' ? raw : (raw && raw.toString ? raw.toString() : '');
return [{ json: { file: loopItem.file, issues: loopItem.issues, originalHtml: html } }];

const item = $input.first().json;
const filePath = item.file || '';
const isTool = filePath.includes('/tools/');
return [{ json: { ...item, claude_model: isTool ? 'claude-sonnet-4-20250514' : 'claude-haiku-4-5-20251001', claude_max_tokens: isTool ? 8000 : 4000 } }];

const loopItem = $('A4_Loop_Failed').item.json;
const content = $input.first().json.content;
let text = '';
if (Array.isArray(content) && content[0] && content[0].text) text = content[0].text;
else if (typeof content === 'string') text = content;
return [{ json: { file: loopItem.file, data: text } }];

const item = $input.first().json;
const fixedHtml = item.data || '';
const base = $env.TEMP_CONTENT || '/temp-content';
const filePath = base + '/' + (item.file || '');
return [{ json: { ...item, writeData: { data: fixedHtml, fileName: filePath } } }];

const loopFile = ($('A4_Loop_Failed').item.json.file || '').replace(/\\/g, '/');
const data = $input.first().json.data || $input.first().binary?.data;
let results = [];
try {
  const str = typeof data === 'string' ? data : (data && data.toString ? data.toString() : '[]');
  results = JSON.parse(str);
} catch (e) {}
const one = results.find(r => (r.file || '').replace(/\\/g, '/') === loopFile) || results[0] || {};
return [{ json: { file: one.file || loopFile, status: one.status || 'FAIL', issues: one.issues || [] } }];

const staticData = $getWorkflowStaticData('global');
staticData.approvedCount = (staticData.approvedCount || 0) + 1;
return $input.all();

const loopItem = $('A4_Loop_Failed').item.json;
const parseItem = $input.first().json;
const issues = Array.isArray(parseItem.issues) ? parseItem.issues.join('; ') : (parseItem.issues || '');
return [{ json: { file: loopItem.file, issues, attempts: 2 } }];

const loopItem = $('A4_Attempt_2_Prepare').item.json;
const raw = $input.first().json.data || $input.first().binary?.data;
let html = typeof raw === 'string' ? raw : (raw && raw.toString ? raw.toString() : '');
return [{ json: { file: loopItem.file, issues: loopItem.issues, originalHtml: html } }];

const item = $input.first().json;
const filePath = item.file || '';
const isTool = filePath.includes('/tools/');
return [{ json: { ...item, claude_model: isTool ? 'claude-sonnet-4-20250514' : 'claude-haiku-4-5-20251001', claude_max_tokens: isTool ? 8000 : 4000 } }];

const prev = $('A4_Attempt_2_Prepare').item.json;
const content = $input.first().json.content;
let text = '';
if (Array.isArray(content) && content[0] && content[0].text) text = content[0].text;
else if (typeof content === 'string') text = content;
return [{ json: { file: prev.file, data: text } }];

const item = $input.first().json;
const fixedHtml = item.data || '';
const base = $env.TEMP_CONTENT || '/temp-content';
const filePath = base + '/' + (item.file || '');
return [{ json: { ...item, writeData: { data: fixedHtml, fileName: filePath } } }];

const prevFile = ($('A4_Attempt_2_Prepare').item.json.file || '').replace(/\\/g, '/');
const data = $input.first().json.data || $input.first().binary?.data;
let results = [];
try {
  const str = typeof data === 'string' ? data : (data && data.toString ? data.toString() : '[]');
  results = JSON.parse(str);
} catch (e) {}
const one = results.find(r => (r.file || '').replace(/\\/g, '/') === prevFile) || results[0] || {};
return [{ json: { file: one.file || prevFile, status: one.status || 'FAIL', issues: one.issues || [] } }];

const staticData = $getWorkflowStaticData('global');
const count = staticData.approvedCount || 0;
return [{ json: { anyApproved: count > 0 } }];

const raw = $input.first().json.data || $input.first().binary?.data;
let report = {};
try {
  const str = typeof raw === 'string' ? raw : (raw && raw.toString ? raw.toString() : '{}');
  report = JSON.parse(str);
} catch (e) {}
const status = report.status || {};
return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    indexed_pages: status.indexed_pages ?? 0,
    clicks: status.clicks ?? 0,
    impressions: status.impressions ?? 0,
    ctr: status.ctr ?? 0,
    top_pages: report.top_pages || [],
    recommendations: report.report?.recommendations || []
  }
}];

const recs = $json.recommendations || [];
const contentRec = recs.find(r => r.type === 'content');
if (!contentRec) return [];
return [{
  json: {
    winning_type: (contentRec.issue || '').match(/(tool_reviews|comparisons|categories)/)?.[0] || 'unknown',
    recommendation: contentRec.action || '',
    timestamp: new Date().toISOString()
  }
}];

const winning = $json.winning_type;
let priorityBoost = {
  contentType: 'tool_reviews',
  action: 'boost_priority',
  reason: winning + ' performing best — prioritizing more tool reviews',
  timestamp: new Date().toISOString()
};
if (winning === 'comparisons') {
  priorityBoost.contentType = 'comparisons';
  priorityBoost.action = 'create_more_comparisons';
}
if (winning === 'categories') {
  priorityBoost.contentType = 'categories';
  priorityBoost.action = 'refresh_category_pages';
}
return [{ json: priorityBoost }];

const tools = $input.all();
const winning = $('A6_Adjust_Priorities').first().json.contentType;
if (winning !== 'tool_reviews') return [];
const boosted = tools
  .filter(t => (t.json.Priority || 0) < 8 && t.json.Status === 'PENDING_CONTENT')
  .slice(0, 10)
  .map((t, i) => ({
    json: {
      'Tool Name': t.json['Tool Name'],
      Priority: Math.min((t.json.Priority || 5) + 2, 10),
      RowNumber: t.json.__rowNumber != null ? t.json.__rowNumber : (2 + i)
    }
  }));
return boosted;

const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const yesterdayStr = yesterday.toISOString().split('T')[0];
const tools = $input.all();
const filtered = tools.filter(item => {
  const dateAdded = item.json['Date Added'];
  return dateAdded && dateAdded.startsWith(yesterdayStr);
});
if (filtered.length === 0) {
  return [];
}
const sorted = filtered.sort((a, b) => {
  return (b.json['Priority'] || 0) - (a.json['Priority'] || 0);
});
return sorted.slice(0, 3);

const tools = $input.all();
const email_tools = tools.map(t => ({
  name: t.json['Tool Name'] || t.json.name || 'Tool',
  category: t.json['Category'] || t.json.category || 'General',
  price: t.json['Price'] || t.json.pricing?.lifetime || t.json.pricing?.monthly || 'Check site',
  deal_url: t.json['Deal URL'] || t.json.deal_url || '',
  description: t.json['Description'] || t.json.description || ''
}));
return [{ json: { email_tools } }];

const response = $input.first().json;
let text = '';
if (Array.isArray(response.content) && response.content[0] && response.content[0].text) text = response.content[0].text;
else if (typeof response.body === 'string') text = response.body;
let subject = 'AI Tool Deals';
let html_content = '';
try {
  const stripped = text.replace(/\\n/g, ' ').replace(/```json\\n?|```/g, '').trim();
  const parsed = JSON.parse(stripped);
  subject = parsed.subject || subject;
  html_content = parsed.html_content || parsed.htmlContent || '';
} catch (e) {
  html_content = text;
}
return [{ json: { subject, html_content } }];
